    CONSTRAINT fk_notes_customer FOREIGN KEY (customer_id) REFERENCES sales.customers (id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS ix_notes_customer ON sales.notes (customer_id);

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'uq_customers_mail' AND conrelid = 'sales.customers'::regclass) THEN ALTER TABLE sales.customers ADD CONSTRAINT uq_customers_mail UNIQUE NULLS NOT DISTINCT (email); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_customers_balance' AND conrelid = 'sales.customers'::regclass) THEN ALTER TABLE sales.customers ADD CONSTRAINT ck_customers_balance CHECK (balance >= -100); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_orders_total' AND conrelid = 'sales.orders'::regclass) THEN ALTER TABLE sales.orders ADD CONSTRAINT ck_orders_total CHECK (total >= 0); END IF; END $$;

