DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_orders_customer' AND conrelid = 'sales.orders'::regclass) THEN ALTER TABLE sales.orders ADD CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES sales.customers (id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE; END IF; END $$;

CREATE OR REPLACE VIEW sales.customer_order_list AS
SELECT c.id, c.name, o.number FROM sales.customers c JOIN sales.orders o ON o.customer_id = c.id;
COMMENT ON VIEW sales.customer_order_list IS 'Every customer with each order.';

CREATE OR REPLACE VIEW sales.customer_order_totals (customer_id, order_count) AS
SELECT id, count(*) FROM sales.customer_order_list GROUP BY id;

CREATE OR REPLACE VIEW sales.active_customers AS
SELECT id, code, status FROM sales.customers WHERE status = 'A'
WITH CHECK OPTION;

CREATE MATERIALIZED VIEW IF NOT EXISTS sales.order_counts AS
SELECT customer_id, count(*) AS order_count FROM sales.orders GROUP BY customer_id;
COMMENT ON MATERIALIZED VIEW sales.order_counts IS 'Orders per customer, stored.';

ALTER SEQUENCE IF EXISTS sales.order_numbers RENAME TO order_number_seq;

ALTER SEQUENCE sales.order_number_seq INCREMENT BY 5 MAXVALUE 999999999 CYCLE;

